from pathlib import Path
import json,re
w=Path(__file__).parent
ledger=[json.loads(s) for s in (w/'source-ledger.jsonl').read_text().splitlines()]
by={}
for s in ledger:
 m=re.search(r'\[((?:V[12]-\d+)|(?:[A-Z]+\d+))\]',s['quote'])
 if m: by[m[1]]=s
reports={s['anchor']:s for s in ledger if s['path']=='input/report.md' and s['anchor'].startswith('C09-ERR-')}
rows=[
('refuted','invalid_inference','refuted',['V1-01','V1-02','V1-05','V2-01','P01'],'Did L01 fail its historical delay demonstration because its maximum exceeds today\'s threshold?',['L01 was tested May 20 under revision 1; the transition explicitly preserves historical rules.','Its three valid values 110,115,118 all satisfy the applicable inclusive 120 limit. Applying the later 100 limit retroactively is invalid.'],'Retain L01\'s historical delay pass; do not infer full release from it.','Audit.within Audit.Unit.l01 = true'),
('refuted','invalid_inference','refuted',['V2-01','V2-02','P02','X01','AUTH01'],'Does N02 pass its June 3 NORMAL delay requirement under the old 120 limit?',['June 3 tests use revision 2 and NORMAL 100; the Annex expressly excludes N02.','The valid third observation is 101, above 100, and release was explicitly denied. Comparison with obsolete 120 is irrelevant to the applicable requirement.'],'Report N02\'s failed 101-millisecond current run.','Audit.within Audit.Unit.n02 = false'),
('supported','sufficient','proved',['V2-02','P02','CAL01'],'Do all three actual valid N01 delay runs meet 100 milliseconds?',['P02 identifies N01 at 20 degrees under NORMAL with three valid observations and both channels measured.','The values 92,95,99 each satisfy the inclusive 100 limit. This supports the narrow delay assertion.'],'Retain the bounded N01 delay finding; separate other release requirements.','Audit.within Audit.Unit.n01 = true'),
('refuted','invalid_inference','refuted',['V2-02','V2-06','P02','X01'],'Did every named NORMAL unit pass every required delay run?',['N02 is a named NORMAL unit at 20 degrees, tested after revision 2 began, without an applicable exception.','Its explicitly valid 101 observation exceeds 100. That one in-domain counterexample refutes the universal, independently of missing N03 evidence.'],'Replace the universal with per-unit outcomes; name N02 as the counterexample.','¬ (∀ u, Audit.normal u = true → Audit.within u = true)'),
('refuted','invalid_inference','refuted',['V2-04','X01','X02','P03','CAL01','AUTH01'],'Did E17 fail because its maximum of 108 exceeds the general NORMAL limit?',['Annex X was authorized for E17 NORMAL from June 2 09:00 through June 4 18:00; its June 3 runs at 20 degrees are in scope.','The applicable limit is 110, not 100. All values 104,108,106 meet 110. The source separately records valid runs, channels, fault closure and authorized release.'],'Report the bounded E17 pass under the incorporated exception, retaining its identity and dates.','Audit.within Audit.Unit.e17 = true'),
('refuted','invalid_inference','refuted',['X01','X02','X03','V2-04'],'Does Annex X extend the 110 threshold to N02?',['The approved exception names E17 only and explicitly excludes N02, regardless of shared hardware.','The broad proposal was rejected; the complete bounded exception register supplies no N02 exception.'],'Keep N02 at its general 100 limit.','Audit.annexApplies Audit.Unit.n02 = false'),
('refuted','invalid_inference','refuted',['V2-02','P04','AP01','CAL01'],'Did C01 fail its applicable profile because its maximum is above 100?',['C01 is COLD at 5 degrees with a current cold-fixture certificate; the profile limit is 150.','Its three valid values 142,145,149 all meet 150. The NORMAL limit does not apply to this event.'],'Report C01\'s COLD demonstration pass without extending it to other temperatures.','Audit.within Audit.Unit.c01 = true'),
('undetermined','insufficient_support','blocked',['AP02','P05','V2-03','V1-04'],'Can the unmeasured N03 channel B outcome be predicted as passing?',['No channel B measurement is supplied, and AP02 expressly distinguishes missing evidence from an observed outcome.','The favorable first delay value and neighboring units cannot determine what an unmeasured channel would have done. Full-corpus review finds no substitute evidence.'],'Obtain a valid channel B measurement; retain a support gap without declaring physical failure.',None),
('refuted','invalid_inference','refuted',['CAL01','V2-05','P05'],'Was K2 current during the June 3 N03 run because it was renewed June 5?',['K2 affirmatively expired June 1 at 23:59. Its use on June 3 is after expiry.','The June 5 renewal has no retrospective clause and cannot establish current calibration two days earlier. This is contrary evidence, not merely an absent certificate.'],'Record expired calibration at the N03 run; distinguish later renewal.','¬ Audit.n03RunDay ≤ Audit.k2ExpiryDay'),
('refuted','invalid_inference','refuted',['P05','AP02','V2-05','V1-04'],'Is X99 a valid 85-millisecond measurement usable as N03\'s missing repetition?',['The raw value is expressly labeled INVALID following synchronization loss.','Invalid traces contribute no valid run; identity-specific repetition cannot be repaired by copying another trace. Invalidity alone refutes the compound assertion.'],'Exclude X99 from valid repetitions and identify the N03 missing/aborted runs.','Audit.x99Valid ≠ true'),
('refuted','invalid_inference','refuted',['V2-03','V1-03','FC01','FC04'],'Does a passing delay alone suffice for full release under the specified route?',['V2-03 requires delay, current calibration, both channels, fault closure and authorized signature.','A model with passing delay and absent fault closure satisfies the definition but does not release. This refutes the claimed sufficiency of delay alone, not the actual physical safety of an untested unit.'],'Require evidence for every release conjunct.','¬ (∀ c b f s : Bool, Audit.release true c b f s = true)'),
('undetermined','insufficient_support','blocked',['X04','V1-03','FC05'],'Must every conceivable compliant assurance method necessarily use the supplied three-run route?',['The documents give a sufficient bounded route, not a necessity theorem over all methods.','No alternative argument is supplied for N03, but absence of alternatives does not prove no alternative can exist. Neither a necessity proof nor a concrete compliant alternative refuting it is supplied.'],'Limit the assertion to the listed route; request an explicit necessity rule before generalizing.',None),
('undetermined','insufficient_support','blocked',['AP01','AP03','V2-06','V1-01'],'Does the packet establish safety at every temperature over the design\'s entire lifetime?',['The evidence is bounded laboratory delay/release demonstration, with no HOT route above 30 degrees or route below zero.','No lifetime, population, mechanical or network argument supplies the additional scope; undefined global safety cannot be inferred from finite favorable measurements.','This absence does not prove unsafe operation at every omitted condition.'],'State only the supported profile/event results; obtain defined lifetime and full-temperature criteria and evidence for the broader claim.',None),
('not_applicable','nonformal','not_attempted',['V2-06','AP03'],'Is there a supplied formal criterion for the specification being beautifully organized?',['The cited review-universe text defines finite scope, not aesthetic quality.','AP03 places beauty outside threshold predicates absent a separate criterion.'],'Label as an editorial opinion or define an assessment rubric.',None)]
findings=[];docs={d['id']:d for d in json.loads((w/'ingestion.json').read_text())['documents']}
for i,(state,arg,formal,keys,q,reason,rec,target) in enumerate(rows,1):
 cid=f'C09-ERR-{i:02d}'; evidence=[]
 for key in keys:
  s=by[key];evidence.append({'path':s['path'],'anchor':s['anchor'],'quote':s['quote'],'original_path':docs[s['document_id']]['external'],'semantic_marker':key})
 # Retain original table coordinates for each referenced threshold table.
 for key in ['V1-02','V2-02']:
  if key in keys:
   path=by[key]['path']
   for s in ledger:
    if s['path']==path and s['anchor'].startswith('docx-table-'):
     evidence.append({'path':path,'anchor':s['anchor'],'quote':s['quote'],'original_path':docs[s['document_id']]['external'],'semantic_marker':key+' table'})
 findings.append({'claim_id':cid,'report_quote':reports[cid]['quote'].split('\n\nCitations:')[0],'report_anchor':cid,'parent_finding':cid,'atomic_target':q,'question':q,'evidence':evidence,'rules':['V2-01 selects version by test execution; V2-02 and V1-02 select profile thresholds; Annex X narrows the E17 exception.','V2-03 release is a conjunction; V2-05 invalidity and calibration chronology cannot be replaced by favorable numbers.','A supplied sufficient route does not establish universal necessity, missing measurements do not predict outcomes, and finite tests do not establish unbounded safety.'],'assumptions':['The fictional document authorities, exact integer values, profiles and event dates are accepted as supplied. Threshold selection is explicitly source-linked in the model notes.'],'reasoning':[f'{n}. {r}' for n,r in enumerate(reason,1)],'semantic_state':state,'argument_status':arg,'formal_status':formal,'proofs':[] if target is None else [{'module':'Audit','theorem':f'Audit.claim{i:02d}','relation':'supports' if state=='supported' else 'refutes','target':target}],'limits':['This concerns the named synthetic test events and the narrow stated assurance route, not certification of actual safety hardware.','Formal targets encode reviewed rule selections; source authenticity and semantic fidelity remain outside kernel checking. Missing/invalid data are never silently promoted to valid observations.'],'recommendation':rec})
(w/'findings.json').write_text(json.dumps(findings,indent=2,ensure_ascii=False)+'\n')
(w/'claims.json').write_text(json.dumps({'claims':[{'claim_id':f['claim_id'],'exact_claim':f['report_quote'],'report_anchor':f['report_anchor'],'atomic_target':f['atomic_target'],'coverage':'assessed'} for f in findings],'excluded_claims':[]},indent=2)+'\n')
